// ListAgents List agents as trees, by project name, then name
//
// The agents of the project named by project, or of the project whose
// worktree holds dir, or of every project without either; every state
// is listed. The top level has the agents with no parent, the rest are
// in their parents' children.
//
// Errors: invalid_path, not_found.
//
// Corresponds with GET /v1/agents (the `ListAgents` operationId).
func (c *Client) ListAgents(ctx context.Context, params *ListAgentsParams, reqEditors ...RequestEditorFn) (*http.Response, error) {
	req, err := NewListAgentsRequest(c.Server, params)
	if err != nil {
		return nil, err
	}
	req = req.WithContext(ctx)
	if err := c.applyEditors(ctx, req, reqEditors); err != nil {
		return nil, err
	}
	return c.Client.Do(req)
}

// CreateAgentWithBody Create an agent and start its AI coding agent
//
// Without project, the agent belongs to the project whose worktree
// holds dir, and starts there. With it, in dir when dir is in the
// project, else in the project's clone path. With parent, it is a child
// of that agent: it belongs to the parent's project and starts in the
// parent's dir, whatever dir is.
//
// With worktree, it starts in that worktree of the project instead:
// "main" is the clone, any other name matches the base name of a
// worktree's path. A name that matches none creates the worktree in
// <project root>/.worktrees/<name>, on a new branch of that name from the
// HEAD of where it would otherwise start, and excludes .worktrees from
// git unless git already ignores it. A worktree created stays when the
// agent then fails, and the next request finds it.
//
// An agent that does not start is left failed and returns start_failed
// with the agent under details.agent.
//
// Errors: agent_removed, branch_exists, invalid_name, invalid_path,
// name_taken, not_found, path_exists, project_closed, start_failed,
// worktree_failed.
//
// Takes any type of body and a specified content type.
//
// Corresponds with POST /v1/agents (the `CreateAgent` operationId).
func (c *Client) CreateAgentWithBody(ctx context.Context, contentType string, body io.Reader, reqEditors ...RequestEditorFn) (*http.Response, error) {
	req, err := NewCreateAgentRequestWithBody(c.Server, contentType, body)
	if err != nil {
		return nil, err
	}
	req = req.WithContext(ctx)
	if err := c.applyEditors(ctx, req, reqEditors); err != nil {
		return nil, err
	}
	return c.Client.Do(req)
}

